import React, { useEffect, useState } from 'react'
import { MapContainer, TileLayer, Marker, Popup, useMapEvents } from 'react-leaflet'
import L from 'leaflet'
import 'leaflet/dist/leaflet.css'
import { supabase } from './supabaseClient'
import SiteForm from './SiteForm'
import AIReimager from './AIReimager'

// fix marker icons
delete L.Icon.Default.prototype._getIconUrl
L.Icon.Default.mergeOptions({
  iconRetinaUrl: require('leaflet/dist/images/marker-icon-2x.png'),
  iconUrl: require('leaflet/dist/images/marker-icon.png'),
  shadowUrl: require('leaflet/dist/images/marker-shadow.png'),
})

function AddMarkerOnClick({ onMapClick }) {
  useMapEvents({
    click(e) { onMapClick(e.latlng) }
  })
  return null
}

function Map({ user, profile }) {
  const [sites, setSites] = useState([])
  const [userLocation, setUserLocation] = useState([51.9, -8.47])
  const [loading, setLoading] = useState(true)
  const [showForm, setShowForm] = useState(false)
  const [selectedPosition, setSelectedPosition] = useState(null)
  const [showAIModal, setShowAIModal] = useState(false)
  const [selectedSite, setSelectedSite] = useState(null)

  useEffect(() => {
    loadSites()
    if (navigator.geolocation) {
      navigator.geolocation.getCurrentPosition((pos) => {
        setUserLocation([pos.coords.latitude, pos.coords.longitude])
      })
    }
  }, [])

  const loadSites = async () => {
    try {
      const { data, error } = await supabase
        .from('derelict_sites')
        .select(`
          *,
          profiles:user_id (username, avatar_url)
        `)
        .order('created_at', { ascending: false })
      
      if (error) throw error
      setSites(data || [])
    } catch (err) {
      console.error('Error loading sites:', err)
      alert('Error loading sites.')
    } finally {
      setLoading(false)
    }
  }

  const handleMapClick = (latlng) => {
    setSelectedPosition(latlng)
    setShowForm(true)
  }

  const handleSiteAdded = (newSite) => {
    setSites([newSite, ...sites])
  }

  const handleSignOut = async () => {
    await supabase.auth.signOut()
  }

  if (loading) return (
    <div style={{
      display: 'flex', alignItems: 'center', justifyContent: 'center', height: '100vh'
    }}>
      Loading map…
    </div>
  )

  return (
    <div style={{ height: '100vh', width: '100%' }}>
      {/* Top bar */}
      <div style={{
        position: 'absolute',
        top: 10,
        left: '50%',
        transform: 'translateX(-50%)',
        zIndex: 1000,
        background: 'white',
        padding: '10px 20px',
        borderRadius: 8,
        boxShadow: '0 2px 10px rgba(0,0,0,0.2)',
        display: 'flex',
        alignItems: 'center',
        gap: 15
      }}>
        <div>
          🏚️ <strong>{sites.length}</strong> derelict sites found
        </div>
        <div style={{ borderLeft: '1px solid #ddd', paddingLeft: 15 }}>
          👤 <strong>@{profile.username}</strong>
        </div>
      </div>

      {/* Sign out button */}
      <button
        onClick={handleSignOut}
        style={{
          position: 'absolute',
          top: 10,
          right: 10,
          zIndex: 1000,
          background: '#f44336',
          color: 'white',
          border: 'none',
          padding: '8px 16px',
          borderRadius: 6,
          cursor: 'pointer',
          fontWeight: 'bold',
          fontSize: 14
        }}
      >
        Sign Out
      </button>

      <MapContainer center={userLocation} zoom={13} style={{ height: '100%', width: '100%' }}>
        <TileLayer
          url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png"
          attribution='&copy; OpenStreetMap contributors'
        />
        <AddMarkerOnClick onMapClick={handleMapClick} />

        {sites.map((site) => (
          <Marker key={site.id} position={[site.latitude, site.longitude]}>
            <Popup maxWidth={300}>
              <div>
                <strong style={{ fontSize: 16 }}>{site.name}</strong>
                
                {/* Show who discovered it */}
                {site.profiles && (
                  <div style={{ 
                    fontSize: 12, 
                    color: '#666', 
                    marginTop: 5,
                    marginBottom: 10 
                  }}>
                    Discovered by <strong>@{site.profiles.username}</strong>
                  </div>
                )}

                {site.photo_url && (
                  <img
                    src={site.photo_url}
                    alt={site.name}
                    style={{ 
                      width: '100%', 
                      height: 150, 
                      objectFit: 'cover', 
                      marginTop: 10, 
                      borderRadius: 6 
                    }}
                  />
                )}
                
                {site.description && (
                  <p style={{ marginTop: 10, fontSize: 14 }}>{site.description}</p>
                )}
                
                <small style={{ color: '#666', display: 'block', marginTop: 5 }}>
                  {new Date(site.created_at).toLocaleDateString()}
                </small>
                
                <button
                  onClick={() => { setSelectedSite(site); setShowAIModal(true) }}
                  style={{
                    marginTop: 10,
                    width: '100%',
                    padding: 8,
                    background: '#9C27B0',
                    color: '#fff',
                    border: 0,
                    borderRadius: 6,
                    fontSize: 14,
                    fontWeight: 'bold',
                    cursor: 'pointer'
                  }}
                >
                  ✨ Reimagine with AI
                </button>
              </div>
            </Popup>
          </Marker>
        ))}
      </MapContainer>

      {showForm && selectedPosition && (
        <SiteForm 
          position={selectedPosition} 
          userId={user.id}
          onClose={() => setShowForm(false)} 
          onSiteAdded={handleSiteAdded} 
        />
      )}

      {showAIModal && selectedSite && (
        <AIReimager site={selectedSite} onClose={() => setShowAIModal(false)} />
      )}
    </div>
  )
}

export default Map
